import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { BuildingEntity } from '../Entity/BuildingEntity';
import { BUILDING_CONFIG } from '../Config/BuildingConfig';
import { SYNERGY_TABLE, NEIGHBOR_OFFSETS } from '../Config/SynergyConfig';
import { HallEvents } from '../HallEvents';

export class SynergySystem implements System {
    private _world: World = null!;

    onStart(world: World): void {
        this._world = world;
        // 建造、拆除、升级都会影响相性，全量重算
        world.bus.on(HallEvents.BUILD_COMPLETED, this._recalcAll, this);
        world.bus.on(HallEvents.BUILD_REMOVED, this._recalcAll, this);
        world.bus.on(HallEvents.UPGRADE_COMPLETED, this._recalcAll, this);
    }

    onDestroy(world: World): void {
        world.bus.off(HallEvents.BUILD_COMPLETED, this._recalcAll, this);
        world.bus.off(HallEvents.BUILD_REMOVED, this._recalcAll, this);
        world.bus.off(HallEvents.UPGRADE_COMPLETED, this._recalcAll, this);
        this._world = null!;
    }

    onTick(world: World, dt: number): void {
        
    }

    private _recalcAll(): void {
        const all = Array.from(this._world.query<BuildingEntity>('building'));
        const byKey = new Map<string, BuildingEntity>();
        for (const b of all) byKey.set(`${b.gridX},${b.gridY}`, b);

        for (const b of all) {
            b.synergyMultiplier = this._calcMultiplier(b, byKey);
            const config = BUILDING_CONFIG[b.typeId];
            if (config) b.recalc(config);
        }
        this._world.bus.emit(HallEvents.SYNERGY_RECALCULATED);
    }

    private _calcMultiplier(b: BuildingEntity, byKey: Map<string, BuildingEntity>): number {
        const selfConfig = BUILDING_CONFIG[b.typeId];
        if (!selfConfig) return 1;

        let mult = 1;
        for (const off of NEIGHBOR_OFFSETS) {
            const neighbor = byKey.get(`${b.gridX + off.dx},${b.gridY + off.dy}`);
            if (!neighbor) continue;
            const neighborConfig = BUILDING_CONFIG[neighbor.typeId];
            if (!neighborConfig) continue;

            for (const rule of SYNERGY_TABLE) {
                if (this._match(selfConfig.tags, neighborConfig.tags, rule)) {
                    mult += rule.bonus;
                }
            }
        }
        return mult;
    }

    private _match(tagsA: string[], tagsB: string[], rule: { tagA: string; tagB: string }): boolean {
        const aHasA = tagsA.includes(rule.tagA);
        const aHasB = tagsA.includes(rule.tagB);
        const bHasA = tagsB.includes(rule.tagA);
        const bHasB = tagsB.includes(rule.tagB);
        // 双向匹配：A有tagA且B有tagB，或A有tagB且B有tagA
        return (aHasA && bHasB) || (aHasB && bHasA);
    }
}